/* ============================
   CSS Custom Properties & Reset
   ============================ */

:root {
    --color-primary: #1a1a1a;
    --color-secondary: #f5f5f5;
    --color-accent: #d4af37;
    --color-text: #333;
    --color-text-light: #666;
    --color-border: #e0e0e0;
    --color-success: #2d8f3f;
    --color-error: #d32f2f;

    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 4rem;

    --font-family-base: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Helvetica Neue', sans-serif;
    --font-family-serif: 'Georgia', serif;

    --font-size-sm: 0.875rem;
    --font-size-base: 1rem;
    --font-size-lg: 1.125rem;
    --font-size-xl: 1.5rem;
    --font-size-2xl: 2rem;
    --font-size-3xl: 2.5rem;

    --line-height-tight: 1.2;
    --line-height-normal: 1.5;
    --line-height-relaxed: 1.75;

    --radius-sm: 4px;
    --radius-md: 8px;
    --radius-lg: 12px;

    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.15);

    --transition-base: all 0.3s ease;
    --transition-fast: all 0.15s ease;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-family-base);
    color: var(--color-text);
    line-height: var(--line-height-normal);
    background-color: #fff;
}

/* Screen reader only class */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* ============================
   Skip Link
   ============================ */

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-primary);
    color: #fff;
    padding: var(--spacing-sm) var(--spacing-md);
    text-decoration: none;
    z-index: 100;
    border-radius: var(--radius-md);
}

.skip-link:focus {
    top: var(--spacing-sm);
    outline: 3px solid var(--color-accent);
    outline-offset: 2px;
}

/* ============================
   Header & Navigation
   ============================ */

.site-header {
    background-color: #fff;
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 50;
    box-shadow: var(--shadow-sm);
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--spacing-md);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
}

.logo-section {
    flex: 0 0 auto;
}

.site-logo {
    font-size: var(--font-size-2xl);
    font-weight: 700;
    color: var(--color-primary);
    font-family: var(--font-family-serif);
    margin: 0;
}

.tagline {
    font-size: var(--font-size-sm);
    color: var(--color-text-light);
    margin: 0;
    font-weight: 400;
}

.main-nav {
    flex: 1;
    display: none;
}

.main-nav.active {
    display: block;
}

.nav-toggle {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    font-size: var(--font-size-xl);
    padding: var(--spacing-xs);
    margin-right: var(--spacing-md);
    color: var(--color-primary);
    position: relative;
}

.nav-toggle:focus {
    outline: 3px solid var(--color-accent);
    outline-offset: 2px;
    border-radius: var(--radius-sm);
}

.hamburger {
    display: block;
    width: 24px;
    height: 20px;
    position: relative;
}

.hamburger::before,
.hamburger::after,
.hamburger {
    content: '';
    position: absolute;
    width: 100%;
    height: 2px;
    background: currentColor;
    left: 0;
    transition: var(--transition-fast);
}

.hamburger::before {
    top: 0;
}

.hamburger::after {
    bottom: 0;
}

.hamburger {
    top: 50%;
    transform: translateY(-50%);
}

.nav-toggle[aria-expanded="true"] .hamburger::before {
    transform: rotate(45deg) translate(10px, 10px);
}

.nav-toggle[aria-expanded="true"] .hamburger {
    opacity: 0;
}

.nav-toggle[aria-expanded="true"] .hamburger::after {
    transform: rotate(-45deg) translate(7px, -7px);
}

.nav-menu {
    list-style: none;
    display: flex;
    gap: var(--spacing-lg);
    align-items: center;
}

.nav-link {
    text-decoration: none;
    color: var(--color-text);
    font-weight: 500;
    font-size: var(--font-size-base);
    position: relative;
    transition: color var(--transition-fast);
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--color-accent);
    transition: width var(--transition-fast);
}

.nav-link:hover::after,
.nav-link:focus::after {
    width: 100%;
}

.nav-link:focus {
    outline: 3px solid var(--color-accent);
    outline-offset: 4px;
    border-radius: var(--radius-sm);
}

.header-actions {
    display: flex;
    gap: var(--spacing-md);
    align-items: center;
}

.icon-btn {
    background: none;
    border: none;
    font-size: var(--font-size-xl);
    cursor: pointer;
    position: relative;
    padding: var(--spacing-xs);
    border-radius: var(--radius-sm);
    transition: var(--transition-fast);
}

.icon-btn:hover {
    background-color: var(--color-secondary);
}

.icon-btn:focus {
    outline: 3px solid var(--color-accent);
    outline-offset: 2px;
}

.cart-badge {
    position: absolute;
    top: -8px;
    right: -8px;
    background: var(--color-accent);
    color: var(--color-primary);
    border-radius: 50%;
    width: 20px;
    height: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    font-weight: 700;
}

/* ============================
   Buttons
   ============================ */

.btn {
    display: inline-block;
    padding: var(--spacing-sm) var(--spacing-lg);
    border: none;
    border-radius: var(--radius-md);
    font-size: var(--font-size-base);
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition-base);
    text-decoration: none;
    text-align: center;
    min-width: 120px;
}

.btn:focus {
    outline: 3px solid var(--color-accent);
    outline-offset: 2px;
}

.btn-primary {
    background-color: var(--color-primary);
    color: #fff;
}

.btn-primary:hover {
    background-color: var(--color-text);
    box-shadow: var(--shadow-md);
}

.btn-primary:active {
    transform: scale(0.98);
}

.btn-secondary {
    background-color: var(--color-secondary);
    color: var(--color-primary);
    border: 2px solid var(--color-border);
}

.btn-secondary:hover {
    background-color: #fff;
    border-color: var(--color-primary);
    box-shadow: var(--shadow-md);
}

.btn-secondary:active {
    transform: scale(0.98);
}

/* ============================
   Main Content
   ============================ */

main {
    min-height: 100vh;
}

/* ============================
   Hero Section
   ============================ */

.hero {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-2xl);
    align-items: center;
    padding: var(--spacing-2xl) var(--spacing-lg);
    max-width: 1200px;
    margin: 0 auto;
    background: linear-gradient(135deg, #f5f5f5 0%, #fafafa 100%);
}

.hero-content h2 {
    font-size: var(--font-size-3xl);
    margin-bottom: var(--spacing-md);
    color: var(--color-primary);
    font-family: var(--font-family-serif);
}

.hero-subtitle {
    font-size: var(--font-size-lg);
    color: var(--color-text-light);
    margin-bottom: var(--spacing-lg);
    line-height: var(--line-height-relaxed);
}

.hero-image {
    width: 100%;
    aspect-ratio: 1;
    background: linear-gradient(135deg, #e8dcc4 0%, #d4c5b0 100%);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-lg);
}

/* ============================
   Sections
   ============================ */

section {
    padding: var(--spacing-2xl) var(--spacing-lg);
    max-width: 1200px;
    margin: 0 auto;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: var(--spacing-2xl);
    gap: var(--spacing-lg);
}

.section-header h2 {
    font-size: var(--font-size-2xl);
    color: var(--color-primary);
    font-family: var(--font-family-serif);
    margin: 0;
}

.section-subtitle {
    font-size: var(--font-size-lg);
    color: var(--color-text-light);
    margin: var(--spacing-md) 0 0;
}

.view-all {
    color: var(--color-primary);
    font-weight: 600;
    text-decoration: none;
    font-size: var(--font-size-base);
    position: relative;
    transition: color var(--transition-fast);
}

.view-all::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 100%;
    height: 2px;
    background: var(--color-accent);
    transform: scaleX(0);
    transform-origin: right;
    transition: transform var(--transition-fast);
}

.view-all:hover::after,
.view-all:focus::after {
    transform: scaleX(1);
    transform-origin: left;
}

.view-all:focus {
    outline: 3px solid var(--color-accent);
    outline-offset: 4px;
    border-radius: var(--radius-sm);
}

/* ============================
   Product Grid
   ============================ */

.featured-products {
    background-color: #fafafa;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
}

.product-card {
    background: #fff;
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: var(--transition-base);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.product-image {
    width: 100%;
    aspect-ratio: 1;
    background: linear-gradient(135deg, #e0e0e0 0%, #d0d0d0 100%);
    border-radius: var(--radius-lg) var(--radius-lg) 0 0;
}

.product-name {
    font-size: var(--font-size-lg);
    font-weight: 600;
    margin: var(--spacing-md) var(--spacing-md) var(--spacing-xs);
}

.product-description {
    font-size: var(--font-size-sm);
    color: var(--color-text-light);
    margin: 0 var(--spacing-md);
    line-height: var(--line-height-normal);
}

.product-rating {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    margin: var(--spacing-md) var(--spacing-md) var(--spacing-sm);
    font-size: var(--font-size-sm);
}

.stars {
    color: var(--color-accent);
    letter-spacing: 2px;
}

.rating-value {
    color: var(--color-text-light);
}

.product-price {
    margin: 0 var(--spacing-md);
}

.price {
    font-size: var(--font-size-xl);
    font-weight: 700;
    color: var(--color-primary);
}

.product-card .btn {
    margin: var(--spacing-md);
    width: calc(100% - var(--spacing-lg) * 2);
    margin-top: auto;
}

/* ============================
   Deals Section
   ============================ */

.deals {
    background-color: #fff;
}

.deals-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
}

.deal-banner {
    background: linear-gradient(135deg, var(--color-primary) 0%, #2a2a2a 100%);
    color: #fff;
    padding: var(--spacing-xl);
    border-radius: var(--radius-lg);
    display: flex;
    flex-direction: column;
    justify-content: center;
    text-align: center;
    grid-column: 1 / -1;
}

.deal-banner h3 {
    font-size: var(--font-size-3xl);
    margin-bottom: var(--spacing-sm);
    font-family: var(--font-family-serif);
}

.deal-subtitle {
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-md);
    opacity: 0.95;
}

.deal-timer {
    font-size: var(--font-size-base);
    margin-bottom: var(--spacing-lg);
    opacity: 0.9;
}

.deal-card {
    background: #f9f9f9;
    border-radius: var(--radius-lg);
    overflow: hidden;
    position: relative;
    transition: var(--transition-base);
    box-shadow: var(--shadow-sm);
}

.deal-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.discount-badge {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background: var(--color-error);
    color: #fff;
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: var(--radius-md);
    font-weight: 700;
    font-size: var(--font-size-sm);
    z-index: 10;
}

.deal-image {
    width: 100%;
    aspect-ratio: 1;
    background: linear-gradient(135deg, #e8d7c3 0%, #d9cbb5 100%);
    border-radius: var(--radius-lg) var(--radius-lg) 0 0;
}

.deal-name {
    font-size: var(--font-size-base);
    font-weight: 600;
    margin: var(--spacing-md);
    color: var(--color-primary);
}

.price-section {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    margin: var(--spacing-sm) var(--spacing-md) var(--spacing-md);
}

.original-price {
    font-size: var(--font-size-sm);
    color: var(--color-text-light);
}

