/**
 * Ecommerce Home Page - Interactive Features
 * Handles navigation, cart functionality, and form interactions
 */

class EcommerceApp {
    constructor() {
        this.cart = [];
        this.cartBadge = document.querySelector('.cart-badge');
        this.navToggle = document.querySelector('.nav-toggle');
        this.navMenu = document.getElementById('nav-menu');
        this.addToCartButtons = document.querySelectorAll('[aria-label*="Add"]');
        this.newsletterForm = document.querySelector('.newsletter-form');

        this.init();
    }

    init() {
        this.setupNavigation();
        this.setupAddToCart();
        this.setupNewsletter();
        this.restoreCart();
    }

    /**
     * Mobile navigation toggle
     */
    setupNavigation() {
        if (this.navToggle) {
            this.navToggle.addEventListener('click', () => {
                const isExpanded = this.navToggle.getAttribute('aria-expanded') === 'true';
                this.navToggle.setAttribute('aria-expanded', !isExpanded);
                this.navMenu.classList.toggle('active');
            });

            // Close menu when clicking on a link
            const navLinks = this.navMenu.querySelectorAll('a');
            navLinks.forEach(link => {
                link.addEventListener('click', () => {
                    this.navToggle.setAttribute('aria-expanded', 'false');
                    this.navMenu.classList.remove('active');
                });
            });

            // Close menu when clicking outside
            document.addEventListener('click', (e) => {
                if (!e.target.closest('.main-nav') && !e.target.closest('.nav-toggle')) {
                    this.navToggle.setAttribute('aria-expanded', 'false');
                    this.navMenu.classList.remove('active');
                }
            });
        }
    }

    /**
     * Add to cart functionality
     */
    setupAddToCart() {
        this.addToCartButtons.forEach(button => {
            button.addEventListener('click', (e) => {
                const productCard = e.target.closest('.product-card, .deal-card');
                if (productCard) {
                    const productName = productCard.querySelector('h3').textContent;
                    const priceText = productCard.querySelector('.price, .deal-price').textContent;

                    this.addToCart({
                        name: productName,
                        price: priceText
                    });

                    // Provide feedback to user
                    this.showFeedback(button, `Added ${productName} to cart`);
                }
            });
        });
    }

    /**
     * Add item to cart
     */
    addToCart(item) {
        this.cart.push(item);
        this.updateCartBadge();
        this.saveCart();
    }

    /**
     * Update cart badge count
     */
    updateCartBadge() {
        if (this.cartBadge) {
            this.cartBadge.textContent = this.cart.length;
        }
    }

    /**
     * Save cart to localStorage
     */
    saveCart() {
        try {
            localStorage.setItem('ecommerce-cart', JSON.stringify(this.cart));
        } catch (e) {
            console.warn('Could not save cart to localStorage:', e);
        }
    }

    /**
     * Restore cart from localStorage
     */
    restoreCart() {
        try {
            const saved = localStorage.getItem('ecommerce-cart');
            if (saved) {
                this.cart = JSON.parse(saved);
                this.updateCartBadge();
            }
        } catch (e) {
            console.warn('Could not restore cart from localStorage:', e);
        }
    }

    /**
     * Newsletter signup form
     */
    setupNewsletter() {
        if (this.newsletterForm) {
            this.newsletterForm.addEventListener('submit', (e) => {
                e.preventDefault();
                const emailInput = this.newsletterForm.querySelector('input[type="email"]');

                if (this.validateEmail(emailInput.value)) {
                    this.showFeedback(
                        this.newsletterForm.querySelector('button'),
                        'Subscribed! Check your email for the discount code.',
                        'success'
                    );
                    emailInput.value = '';
                } else {
                    this.showFeedback(
                        this.newsletterForm.querySelector('button'),
                        'Please enter a valid email address',
                        'error'
                    );
                }
            });
        }
    }

    /**
     * Validate email format
     */
    validateEmail(email) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }

    /**
     * Show feedback message to user
     */
    showFeedback(element, message, type = 'success') {
        const feedback = document.createElement('div');
        feedback.className = `feedback feedback-${type}`;
        feedback.setAttribute('role', 'status');
        feedback.setAttribute('aria-live', 'polite');
        feedback.textContent = message;
        feedback.style.cssText = `
            position: fixed;
            bottom: 20px;
            right: 20px;
            background: ${type === 'success' ? '#2d8f3f' : '#d32f2f'};
            color: white;
            padding: 16px 24px;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
            z-index: 1000;
            animation: slideIn 0.3s ease-out;
        `;

        document.body.appendChild(feedback);

        setTimeout(() => {
            feedback.remove();
        }, 3000);
    }
}

/**
 * Add slide-in animation for feedback
 */
const style = document.createElement('style');
style.textContent = `
    @keyframes slideIn {
        from {
            transform: translateX(400px);
            opacity: 0;
        }
        to {
            transform: translateX(0);
            opacity: 1;
        }
    }

    @media (prefers-reduced-motion: reduce) {
        @keyframes slideIn {
            from {
                transform: none;
                opacity: 0;
            }
            to {
                transform: none;
                opacity: 1;
            }
        }
    }
`;
document.head.appendChild(style);

/**
