    font-weight: 700;
    margin-bottom: var(--spacing-md);
}

.footer-section ul {
    list-style: none;
}

.footer-section a {
    color: #ccc;
    text-decoration: none;
    font-size: var(--font-size-sm);
    display: block;
    padding: var(--spacing-xs) 0;
