const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

async function runDetailedAccessibilityTests() {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    const htmlPath = path.join(__dirname, 'index.html');
    const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

    page.setContent(htmlContent, { waitUntil: 'load' });

    // Load axe-core
    const axeSource = fs.readFileSync('./node_modules/axe-core/axe.min.js', 'utf-8');
    await page.evaluate(axeSource);

    // Initial run
    console.log('=== INITIAL RUN ===');
    let results = await page.evaluate(async () => {
        return await window.axe.run();
    });

    const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bpViolations = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(`WCAG Violations: ${wcagViolations.length}`);
    console.log(`Best Practice: ${bpViolations.length}`);
    console.log(`Passes: ${results.passes.length}`);

    if (wcagViolations.length > 0) {
        console.log('\nWCAG Issues:');
        wcagViolations.forEach(v => {
            console.log(`  - ${v.id} (${v.impact}): ${v.description}`);
            v.nodes.forEach(n => console.log(`    Target: ${JSON.stringify(n.target)}`));
        });
    }

    if (bpViolations.length > 0) {
        console.log('\nBest Practice Warnings:');
        bpViolations.forEach(v => {
            console.log(`  - ${v.id}: ${v.description}`);
            v.nodes.forEach(n => console.log(`    Target: ${JSON.stringify(n.target)}`));
        });
    }

    // Test keyboard navigation
    console.log('\n=== KEYBOARD NAVIGATION TEST ===');
    const focusableElements = await page.evaluate(() => {
        const focusable = document.querySelectorAll('button, a, input, [tabindex]:not([tabindex="-1"])');
        return focusable.length;
    });
    console.log(`Focusable elements: ${focusableElements}`);

    // Test skip link
    console.log('\n=== SKIP LINK TEST ===');
    const skipLinkExists = await page.evaluate(() => {
        const skipLink = document.querySelector('.skip-link');
        return skipLink && skipLink.getAttribute('href') === '#main-content';
    });
    console.log(`Skip link functional: ${skipLinkExists}`);

    // Test heading hierarchy
    console.log('\n=== HEADING HIERARCHY TEST ===');
    const headings = await page.evaluate(() => {
        const h = document.querySelectorAll('h1, h2, h3, h4, h5, h6');
        return Array.from(h).map(el => ({ tag: el.tagName, text: el.textContent.substring(0, 50) }));
    });
    console.log('Heading structure:');
    headings.forEach(h => console.log(`  ${h.tag}: ${h.text}`));

    // Test main landmark
    console.log('\n=== LANDMARK TEST ===');
    const landmarks = await page.evaluate(() => {
        return {
            main: document.querySelector('main') ? 'present' : 'missing',
            header: document.querySelector('header') ? 'present' : 'missing',
            footer: document.querySelector('footer') ? 'present' : 'missing',
            nav: document.querySelectorAll('nav').length
        };
    });
    console.log(`Landmarks: ${JSON.stringify(landmarks)}`);

    // Test images and graphics
    console.log('\n=== IMAGE ALT TEXT TEST ===');
    const images = await page.evaluate(() => {
        const imgs = document.querySelectorAll('[role="img"]');
        return Array.from(imgs).map(img => ({
            hasAriaLabel: img.hasAttribute('aria-label'),
            label: img.getAttribute('aria-label')?.substring(0, 50) || 'none'
        }));
    });
    console.log(`Images with role="img": ${images.length}`);
    images.slice(0, 5).forEach((img, i) => {
        console.log(`  Image ${i+1}: aria-label present: ${img.hasAriaLabel}`);
    });

    // Test form labels
    console.log('\n=== FORM LABEL TEST ===');
    const inputs = await page.evaluate(() => {
        const inp = document.querySelectorAll('input');
        return Array.from(inp).map(input => ({
            type: input.type,
            hasLabel: !!input.closest('label') || document.querySelector(`label[for="${input.id}"]`),
            id: input.id,
            ariaLabel: input.getAttribute('aria-label')
        }));
    });
    console.log(`Input fields: ${inputs.length}`);
    inputs.forEach((inp, i) => {
        console.log(`  Input ${i+1}: type=${inp.type}, has label/aria: ${inp.hasLabel || !!inp.ariaLabel}`);
    });

    // Final axe run
    console.log('\n=== FINAL AXE RUN ===');
    results = await page.evaluate(async () => {
        return await window.axe.run();
    });

    const finalWcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    console.log(`Final WCAG violations: ${finalWcag.length}`);
    console.log(`Final best practice: ${results.violations.filter(v => v.tags.includes('best-practice')).length}`);
    console.log(`Final passes: ${results.passes.length}`);

    await browser.close();

    process.exit(finalWcag.length > 0 ? 1 : 0);
}

